  for (int row = blockIdx.x * NumWarps + warp; row < batch; row += row_stride) {
    float pos_acc = 0.0f;
    float neg_acc = 0.0f;
    const long long row_off = static_cast<long long>(row) * dim;
    const T* __restrict__ arow = A + row_off;
    const T* __restrict__ prow = P + row_off;
    const T* __restrict__ nrow = N + row_off;
    const unsigned long long addr_bits =
        reinterpret_cast<unsigned long long>(arow) |
        reinterpret_cast<unsigned long long>(prow) |
        reinterpret_cast<unsigned long long>(nrow);
    const bool vec_ok = (dim >= 4) && ((addr_bits & 15ull) == 0ull);
    if (vec_ok) {
      const float4* __restrict__ A4 = reinterpret_cast<const float4*>(arow);
      const float4* __restrict__ P4 = reinterpret_cast<const float4*>(prow);
      const float4* __restrict__ N4 = reinterpret_cast<const float4*>(nrow);
      const int dim4 = dim >> 2;
#pragma unroll 4
      for (int i = lane; i < dim4; i += 32) {
        const float4 a = __ldcs(&A4[i]);
        const float4 p = __ldcs(&P4[i]);
        const float4 n = __ldcs(&N4[i]);
        const float dp0 = a.x - p.x;
        const float dp1 = a.y - p.y;
        const float dp2 = a.z - p.z;
        const float dp3 = a.w - p.w;
        const float dn0 = a.x - n.x;
        const float dn1 = a.y - n.y;
        const float dn2 = a.z - n.z;
        const float dn3 = a.w - n.w;
        pos_acc += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
        neg_acc += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
      }
      const int tail = dim4 << 2;
      for (int i = tail + lane; i < dim; i += 32) {
        const float a = static_cast<float>(__ldcs(arow + i));
        const float p = static_cast<float>(__ldcs(prow + i));
        const float n = static_cast<float>(__ldcs(nrow + i));
        const float d_pos = a - p;
        const float d_neg = a - n;
        pos_acc += d_pos * d_pos;
        neg_acc += d_neg * d_neg;
      }
    } else {
      for (int i = lane; i < dim; i += 32) {
        const float a = static_cast<float>(__ldcs(arow + i));
        const float p = static_cast<float>(__ldcs(prow + i));
        const float n = static_cast<float>(__ldcs(nrow + i));
        const float d_pos = a - p;
        const float d_neg = a - n;
        pos_acc += d_pos * d_pos;
        neg_acc += d_neg * d_neg;
      }
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
      pos_acc += __shfl_down_sync(full_mask, pos_acc, offset);
      neg_acc += __shfl_down_sync(full_mask, neg_acc, offset);
    }
