      const float dist_pos = fmaxf(sqrtf(fmaxf(pos_acc, 0.0f)), Eps);
      const float dist_neg = fmaxf(sqrtf(fmaxf(neg_acc, 0.0f)), Eps);
      warp_loss += fmaxf(dist_pos - dist_neg + margin, 0.0f);
    }
  }
