      const float n = static_cast<float>(__ldcs(nrow + i));
      const float d_pos = a - p;
      const float d_neg = a - n;
      pos_acc += d_pos * d_pos;
      neg_acc += d_neg * d_neg;
    }
  }
  for (int offset = 16; offset > 0; offset >>= 1) {
    pos_acc += __shfl_down_sync(full_mask, pos_acc, offset);
    neg_acc += __shfl_down_sync(full_mask, neg_acc, offset);
  }
  if (lane == 0) {
    warp_pos[warp] = pos_acc;
    warp_neg[warp] = neg_acc;
  }
  __syncthreads();
  if (warp == 0) {
    float pos_total = (lane < RowBlockWarps) ? warp_pos[lane] : 0.0f;
    float neg_total = (lane < RowBlockWarps) ? warp_neg[lane] : 0.0f;
    for (int offset = RowBlockWarps / 2; offset > 0; offset >>= 1) {
      pos_total += __shfl_down_sync(full_mask, pos_total, offset);
      neg_total += __shfl_down_sync(full_mask, neg_total, offset);
    }
