    }
  }
}
template <typename T>
__global__ void reduce_row_losses_kernel(const T* __restrict__ RowLoss,
                                          T* __restrict__ Out,
                                          int batch,
                                          float inv_batch)
{
  const int tid = threadIdx.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const unsigned full_mask = 0xffffffffu;
  __shared__ float warp_sums[RowBlockWarps];
  float acc = 0.0f;
  for (int i = tid; i < batch; i += RowBlockThreads) {
    acc += static_cast<float>(__ldcs(RowLoss + i));
  }
  for (int offset = 16; offset > 0; offset >>= 1) {
    acc += __shfl_down_sync(full_mask, acc, offset);
  }
