torch::Tensor triplet_margin_loss(torch::Tensor anchor,
                                  torch::Tensor positive,
                                  torch::Tensor negative,
                                  double margin)
{
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "anchor, positive and negative must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "Only float32 is supported");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "anchor, positive and negative must have identical shapes");
  TORCH_CHECK(anchor.dim() >= 1, "inputs must have at least one dimension");

  auto A = anchor.contiguous();
  auto P = positive.contiguous();
  auto N = negative.contiguous();

  const int64_t batch64 = A.size(0);
  const int64_t numel64 = A.numel();
  TORCH_CHECK(batch64 > 0, "batch dimension must be non-empty");
  TORCH_CHECK(numel64 % batch64 == 0, "invalid flattened feature dimension");

  const int64_t dim64 = numel64 / batch64;
  TORCH_CHECK(batch64 <= INT_MAX && dim64 <= INT_MAX,
              "tensor is too large for this kernel");

  const int batch = static_cast<int>(batch64);
  const int dim = static_cast<int>(dim64);
  const float inv_batch = 1.0f / static_cast<float>(batch);

  auto out = torch::empty({}, A.options());
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (dim >= 1024) {
    auto row_loss = torch::empty({batch64}, A.options());
    dim3 row_grid(static_cast<unsigned int>(batch));
    dim3 row_block(RowBlockThreads);
    triplet_margin_row_loss_kernel<float><<<row_grid, row_block, 0, stream>>>(
        A.data_ptr<float>(),
        P.data_ptr<float>(),
        N.data_ptr<float>(),
        row_loss.data_ptr<float>(),
        batch,
        dim,
        static_cast<float>(margin));
    const auto row_err = cudaGetLastError();
    TORCH_CHECK(row_err == cudaSuccess,
                "triplet_margin_row_loss_kernel launch failed: ",
                cudaGetErrorString(row_err));
    reduce_row_losses_kernel<float><<<1, row_block, 0, stream>>>(
        row_loss.data_ptr<float>(),
        out.data_ptr<float>(),
        batch,
        inv_batch);
    const auto reduce_err = cudaGetLastError();
    TORCH_CHECK(reduce_err == cudaSuccess,
                "reduce_row_losses_kernel launch failed: ",
                cudaGetErrorString(reduce_err));
    return out;
  }
  cudaMemsetAsync(out.data_ptr<float>(), 0, sizeof(float), stream);
  int sm_count = 0;
  cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, A.get_device());
  const int max_blocks = (sm_count > 0) ? sm_count * 8 : 1024;
  const int rows_per_block = 8;
  const int blocks_needed = (batch + rows_per_block - 1) / rows_per_block;
  dim3 grid(blocks_needed < max_blocks ? blocks_needed : max_blocks);
  dim3 block(256);
  triplet_margin_loss_kernel<float><<<grid, block, 0, stream>>>(
      A.data_ptr<float>(),
      P.data_ptr<float>(),
      N.data_ptr<float>(),
      out.data_ptr<float>(),
      batch,
      dim,
      static_cast<float>(margin),
      inv_batch);
  const auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "triplet_margin_loss_kernel launch failed: ",
              cudaGetErrorString(err));
  return out;
}
